from machine import ADC, PWM, Pin
import select
import sys
import time

adc1 = ADC(Pin(1))
adc1.atten(ADC.ATTN_11DB)
pwm3 = PWM(Pin(3), freq=1000, duty=0)
pin13_out = Pin(13, Pin.OUT)
serial_poll = select.poll()
serial_poll.register(sys.stdin, select.POLLIN)
count = 0
lightLevel = 0
message = 0

def tariro_tone(pin, frequency, duration_ms):
    # Play a note on a buzzer, then stop.
    buzzer = PWM(Pin(pin), freq=int(frequency), duty=512)
    time.sleep_ms(int(duration_ms))
    buzzer.deinit()


def brightness(reading):
    return min(max(255 - reading / 4, 0), 255)


def beep(times):
    for i in range(int(times)):
        tariro_tone(8, 880, 100)
        time.sleep_ms(200)

count = 0
print("Night light ready")
beep(2)

while True:
    lightLevel = adc1.read()
    pwm3.duty(int(min(max(brightness(lightLevel), 0), 255) * 1023 / 255))
    if lightLevel < 300:
        pin13_out.value(1)
    else:
        pin13_out.value(0)
    count += 1
    if count % 10 == 0:
        message = "light level: " + str(lightLevel)
        print(message)
    while len(serial_poll.poll(0)) > 0:
        print(sys.stdin.readline().strip())
    time.sleep_ms(100)
